Рекордер записан. Добавляю единый плеер: он останавливает предыдущий звук, сообщает прогресс и скачивает защищённое медиа в кэш с Bearer-токеном.

```json
{"version":1,"taskId":"8a0be3a8-0a9f-4632-89a1-42d645506940","commandId":"write-player-6","operation":"run","headSha":"a4bf6e68d1ec87f6ea1faaf321505c380d437763","command":"cat > apps/mobile/src/audio/player.ts <<'EOF'
declare const require: (moduleName: string) => unknown;

export interface PlayOptions {
  onProgress?: (progress: number, positionMs: number, durationMs: number) => void;
  onEnd?: () => void;
}

interface PlaybackStatus {
  isLoaded: boolean;
  positionMillis?: number;
  durationMillis?: number;
  didJustFinish?: boolean;
}

interface ExpoSound {
  loadAsync(source: { uri: string }, initialStatus?: object, downloadFirst?: boolean): Promise<void>;
  playAsync(): Promise<void>;
  pauseAsync(): Promise<void>;
  stopAsync(): Promise<void>;
  unloadAsync(): Promise<void>;
  setProgressUpdateIntervalAsync(intervalMs: number): Promise<void>;
  setOnPlaybackStatusUpdate(listener: ((status: PlaybackStatus) => void) | null): void;
}

interface FileSystemModule {
  cacheDirectory: string | null;
  getInfoAsync(uri: string): Promise<{ exists: boolean }>;
  downloadAsync(
    url: string,
    fileUri: string,
    options: { headers: Record<string, string> },
  ): Promise<{ uri: string }>;
}

interface TokenStorage {
  getToken(): Promise<string | null> | string | null;
}

let currentSound: ExpoSound | null = null;
let currentOnEnd: (() => void) | undefined;
let playbackGeneration = 0;

function makeCacheKey(value: string): string {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
}

function getTokenStorage(): TokenStorage | null {
  try {
    const module = require('../session/storage') as {
      storage?: TokenStorage;
      default?: TokenStorage;
      getToken?: TokenStorage['getToken'];
    };
    if (module.storage) return module.storage;
    if (module.default) return module.default;
    if (module.getToken) return { getToken: module.getToken };
  } catch {
    return null;
  }
  return null;
}

async function cacheRemoteAudio(url: string): Promise<string> {
  if (/[?&](?:token|access_token)=/i.test(url)) return url;

  const storage = getTokenStorage();
  const token = storage ? await storage.getToken() : null;
  if (!token) throw new Error('Audio playback requires authorization');

  const FileSystem = require('expo-file-system') as FileSystemModule;
  if (!FileSystem.cacheDirectory) throw new Error('Audio cache is unavailable');

  const target = `${FileSystem.cacheDirectory}voice-${makeCacheKey(url)}.m4a`;
  const info = await FileSystem.getInfoAsync(target);
  if (info.exists) return target;
  const result = await FileSystem.downloadAsync(url, target, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return result.uri;
}

async function resolvePlayableUri(uriOrUrl: string): Promise<string> {
  return /^https?:\/\//i.test(uriOrUrl) ? cacheRemoteAudio(uriOrUrl) : uriOrUrl;
}

async function releaseCurrent(notifyEnd: boolean): Promise<void> {
  const sound = currentSound;
  const onEnd = currentOnEnd;
  currentSound = null;
  currentOnEnd = undefined;
  playbackGeneration += 1;
  if (sound) {
    sound.setOnPlaybackStatusUpdate(null);
    try {
      await sound.stopAsync();
    } catch {
      // An unloaded or not-yet-loaded sound is already effectively stopped.
    }
    try {
      await sound.unloadAsync();
    } catch {
      // Cleanup errors do not prevent a later voice message from playing.
    }
  }
  if (notifyEnd) onEnd?.();
}

export async function play(uriOrUrl: string, options: PlayOptions = {}): Promise<void> {
  await releaseCurrent(true);
  const generation = playbackGeneration;
  const playableUri = await resolvePlayableUri(uriOrUrl);
  const Audio = (require('expo-av') as { Audio: { Sound: new () => ExpoSound } }).Audio;
  const sound = new Audio.Sound();
  currentSound = sound;
  currentOnEnd = options.onEnd;

  sound.setOnPlaybackStatusUpdate((status) => {
    if (generation !== playbackGeneration || !status.isLoaded) return;
    const positionMs = status.positionMillis ?? 0;
    const durationMs = status.durationMillis ?? 0;
    const progress = durationMs > 0 ? Math.min(1, positionMs / durationMs) : 0;
    options.onProgress?.(progress, positionMs, durationMs);
    if (status.didJustFinish) void releaseCurrent(true);
  });

  try {
    await sound.loadAsync({ uri: playableUri }, {}, true);
    await sound.setProgressUpdateIntervalAsync(100);
    await sound.playAsync();
  } catch (error) {
    if (currentSound === sound) await releaseCurrent(false);
    throw error;
  }
}

export async function pause(): Promise<void> {
  await currentSound?.pauseAsync();
}

export async function stop(): Promise<void> {
  await releaseCurrent(true);
}
